  function renderWorkspaceCollections(){
    const data=window.QI_WORKSPACE.data,q=workspaceSearch.trim().toLowerCase();
    const matches=id=>{const t=byId.get(id);return !q||[t.name,...t.aliases,...t.tags,data.notes[id]||""].join(" ").toLowerCase().includes(q);};
    const list=(label,ids,key)=>{const shown=ids.filter(matches);return `<section data-saved-list="${key}"><h4>${label} · ${shown.length} / ${ids.length}</h4><div class="profile-collection">${shown.map(id=>`<a class="source-link" href="${theoryLink(id,"workspace")}"><strong>${esc(byId.get(id).name)}</strong>${data.notes[id]?`<span>${esc(data.notes[id].slice(0,180))}</span>`:""}</a>`).join("")||`<p class="muted">${ids.length?"No matches. Try another search or clear the search field.":"Nothing saved in this list yet."}</p>`}</div></section>`;};
