        <p>${theory?esc(theory.name):"Research question"} · reviewed ${esc(item.reviewedAt)}</p>
      </a>`;
    }).join("");
  }

  function renderAll(){
    renderStats();renderLegend();renderGraph();renderTimeline();renderCatalog();renderLineage();renderDetail();renderFormulas();renderQuestions();renderProblems();renderEvidence();renderExplore();
  }
  function switchView(view){
    state.view=view;
    document.querySelectorAll(".tab").forEach(b=>b.classList.toggle("active",b.dataset.view===view));
    $$(".view").forEach(v=>v.classList.remove("active"));
    $("#"+view+"View").classList.add("active");
    if(view==="explore") renderExplore();
    if(view==="compare") renderComparison();
    if(view==="learn") renderLearningPaths();
    if(view==="workspace") renderWorkspace();
    if(view==="questions") renderQuestions();
    if(view==="problems") renderProblems();
    if(view==="evidence") renderEvidence();
    if(view==='coverage')renderCoverage();
    $('#evidenceControls').hidden=!['map','lineage','theory'].includes(view);
    $(".controls").hidden=!["map","timeline","catalog"].includes(view);
    $("#filterScope").hidden=$(".controls").hidden;
    $("#formulaReturn").hidden=view!=="formula" || !safeReturn(new URLSearchParams(location.hash.split("?").slice(1).join("?")).get("returnTo"));
    if(view==="map") setTimeout(renderGraph,0);
    if(view==="lineage") setTimeout(renderThoughtTreeGraph,0);
    if(view==="formula") setTimeout(()=>{renderFormulas();typesetFormulaGrid();},0);
  }
  const views=new Set(["explore","map","timeline","lineage","catalog","formula","compare","problems","evidence","questions","learn","workspace","coverage"]);
  function navigate(hash){
    if(location.hash===hash) applyRoute();
    else location.hash=hash;
  }
  function applyRoute(){
    const [path,query=""]=location.hash.replace(/^#\/?/,"").split("?");
    const params=new URLSearchParams(query);
    const isTheory=path.startsWith("theory/");
    let id=null;
    try { id=isTheory?decodeURIComponent(path.slice(7)):params.get("theory"); } catch {}
    state.evidence=['sourced','documented historical influence','formal mathematical relation','editorial relation'].includes(params.get('evidence'))?params.get('evidence'):'';
    $('#relationEvidence').value=state.evidence;
    if(isTheory){
      state.returnView=views.has(params.get("from"))?params.get("from"):"explore";
      if(state.returnView==="compare" && params.has("compare")) compareIds=[...new Set(params.get("compare").split(",").filter(id=>byId.has(id)))].slice(0,4);
      learningPathId=learningPaths.some(p=>p.id===params.get("path"))?params.get("path"):"";
      state.selected=byId.has(id)?id:null;
      renderDetail();renderLineage();
      const back=$("#backToView");
      back.href=safeReturn(params.get("returnTo")) || (state.returnView==="learn" ? learningHash(learningPathId) : state.returnView==="compare" ? comparisonHash(compareIds) : state.returnView==="formula" && formulaState.theory ? `#/formula?theory=${encodeURIComponent(formulaState.theory)}` : `#/${state.returnView}`);
      back.textContent=`← Back to ${state.returnView==="map"?"network map":state.returnView==="lineage"?"thought trees":state.returnView==="formula"?"formula atlas":state.returnView}`;
      if(!state.selected) $("#theoryDetail").innerHTML='<h3 class="detail-title">Theory not found</h3><p>This link does not match an entry in the current catalog.</p><a class="ghost link-button" href="#/catalog">Browse the catalog</a>';
      switchView("theory");
      document.title=state.selected?`${byId.get(id).name} · Quantum Index`:"Theory not found · Quantum Index";
      $("#theoryDetail").focus({preventScroll:true});
      $("#theoryView").scrollIntoView({block:"start"});
      return;
    }
    const view=views.has(path)?path:"explore";
    if(byId.has(id)) state.selected=id;
    if(view==="compare") compareIds=[...new Set((params.get("ids")||"").split(",").filter(id=>byId.has(id)))].slice(0,4);
    if(view==="learn") learningPathId=learningPaths.some(p=>p.id===params.get("path"))?params.get("path"):"";
    if(view==="problems"){
      const problemId=params.get("problem")||"";
      selectedProblemId=problemById.has(problemId)?problemId:(problems[0]?.id||"");
    }
    if(view==="evidence"){
      evidenceState.search=params.get("search")||"";
      const type=params.get("type")||"";
      evidenceState.type=[...$("#evidenceType").options].some(o=>o.value===type)?type:"";
      const problem=params.get("problem")||"";
      evidenceState.problem=problemById.has(problem)?problem:"";
      $("#evidenceSearch").value=evidenceState.search;$("#evidenceType").value=evidenceState.type;$("#evidenceProblem").value=evidenceState.problem;
    }
    if(view==="questions"){
      questionState.search=params.get("search")||"";
      questionState.disposition=questionDispositions.includes(params.get("disposition"))?params.get("disposition"):"";
      const category=params.get("category")||"";
      questionState.category=[...$("#questionCategory").options].some(o=>o.value===category)?category:"";
      $("#questionSearch").value=questionState.search;$("#questionDisposition").value=questionState.disposition;$("#questionCategory").value=questionState.category;
    }
    if(['map','catalog','timeline'].includes(view)){
      for(const key of ['search','category','kind','status','era']){const el=$(key==='search'?'#search':'#'+key+'Filter'),value=params.get(key)||'';state[key]=key==='search'||[...el.options].some(o=>o.value===value)?value:'';el.value=state[key];}
      state.sourcedOnly=params.get('sourced')==='1';$('#sourcedOnly').checked=state.sourcedOnly;
      if(view==='timeline'){
        timelineState.layer=['all','origins','developments'].includes(params.get('layer'))?params.get('layer'):'all';
        timelineState.eventType=developmentTypes.includes(params.get('eventType'))?params.get('eventType'):'';
        $('#timelineLayer').value=timelineState.layer;
        $('#timelineEventType').value=timelineState.eventType;
      }
      renderGraph();renderCatalog();renderTimeline();
    }
    if(view==='lineage'){const index=trees.findIndex(t=>t.name===params.get('tree'));state.selectedTree=index>=0?index:0;renderTrees();}
    if(view==='formula'){
      const returnTo=safeReturn(params.get('returnTo'));$('#formulaReturn').innerHTML=returnTo?`<a class="ghost link-button" href="${esc(returnTo)}">Back to previous view</a>`:'';
      for(const key of ['search','category','type','theory','review']){const el=$('#formula'+key[0].toUpperCase()+key.slice(1)),value=params.get(key)||'';formulaState[key]=key==='search'||[...el.options].some(o=>o.value===value)?value:'';el.value=formulaState[key];}
    }
    renderDetail();renderLineage();switchView(view);
    document.title="Quantum Index";
  }
  document.querySelectorAll(".tab").forEach(b=>b.addEventListener("click",()=>navigate(b.dataset.view==="compare"?comparisonHash(compareIds):b.dataset.view==="questions"?questionHash():b.dataset.view==="problems"?problemHash():b.dataset.view==="evidence"?evidenceHash():["map","catalog","timeline","formula","lineage"].includes(b.dataset.view)?viewHash(b.dataset.view):`#/${b.dataset.view}`)));
  $("#clearComparison").addEventListener("click",()=>navigate("#/compare"));
  window.addEventListener("hashchange",applyRoute);
  $("#search").addEventListener("input",e=>{state.search=e.target.value;rememberFilters();renderGraph();renderTimeline();renderCatalog();});
  $("#categoryFilter").addEventListener("change",e=>{state.category=e.target.value;rememberFilters();renderGraph();renderTimeline();renderCatalog();});
  $("#kindFilter").addEventListener("change",e=>{state.kind=e.target.value;rememberFilters();renderGraph();renderTimeline();renderCatalog();});
  $("#statusFilter").addEventListener("change",e=>{state.status=e.target.value;rememberFilters();renderGraph();renderTimeline();renderCatalog();});
  $("#eraFilter").addEventListener("change",e=>{state.era=e.target.value;rememberFilters();renderGraph();renderTimeline();renderCatalog();});
  $("#sourcedOnly").addEventListener("change",e=>{state.sourcedOnly=e.target.checked;rememberFilters();renderGraph();renderTimeline();renderCatalog();});
  $("#formulaSearch").addEventListener("input",e=>{formulaState.search=e.target.value;rememberFilters();renderFormulas();});
  $("#formulaCategory").addEventListener("change",e=>{formulaState.category=e.target.value;rememberFilters();renderFormulas();});
  $("#formulaType").addEventListener("change",e=>{formulaState.type=e.target.value;rememberFilters();renderFormulas();});
  $("#formulaTheory").addEventListener("change",e=>{formulaState.theory=e.target.value;rememberFilters();renderFormulas();});
  $('#formulaReview').onchange=e=>{formulaState.review=e.target.value;rememberFilters();renderFormulas();};
  $('#timelineLayer').onchange=e=>{timelineState.layer=e.target.value;rememberFilters();renderTimeline();};
  $('#timelineEventType').onchange=e=>{timelineState.eventType=e.target.value;rememberFilters();renderTimeline();};
  $('#questionSearch').oninput=e=>{questionState.search=e.target.value;history.replaceState(null,'',questionHash());renderQuestions();};
  $('#questionDisposition').onchange=e=>{questionState.disposition=e.target.value;history.replaceState(null,'',questionHash());renderQuestions();};
  $('#questionCategory').onchange=e=>{questionState.category=e.target.value;history.replaceState(null,'',questionHash());renderQuestions();};
  $('#evidenceSearch').oninput=e=>{evidenceState.search=e.target.value;history.replaceState(null,'',evidenceHash());renderEvidence();};
  $('#evidenceType').onchange=e=>{evidenceState.type=e.target.value;history.replaceState(null,'',evidenceHash());renderEvidence();};
  $('#evidenceProblem').onchange=e=>{evidenceState.problem=e.target.value;history.replaceState(null,'',evidenceHash());renderEvidence();};
  $('#relationEvidence').onchange=e=>{state.evidence=e.target.value;if(state.view==='theory'){const params=new URLSearchParams(location.hash.split('?').slice(1).join('?'));if(state.evidence)params.set('evidence',state.evidence);else params.delete('evidence');history.replaceState(null,'',location.hash.split('?')[0]+'?'+params);}else rememberFilters();renderGraph();renderThoughtTreeGraph();renderLineage();renderDetail();};
  $("#resetView").addEventListener("click",()=>{
    Object.assign(state,{search:"",category:"",kind:"",status:"",era:"",sourcedOnly:false});
    Object.assign(timelineState,{layer:"all",eventType:""});Object.assign(questionState,{search:"",disposition:"",category:""});
    $("#search").value="";$("#categoryFilter").value="";$("#kindFilter").value="";$("#statusFilter").value="";$("#eraFilter").value="";$("#sourcedOnly").checked=false;$("#timelineLayer").value="all";$("#timelineEventType").value="";$("#questionSearch").value="";$("#questionDisposition").value="";$("#questionCategory").value="";if(["map","catalog","timeline"].includes(state.view))rememberFilters();renderAll();
  });
  window.addEventListener("resize",()=>{if(state.view==="map")renderGraph();});
  renderTrees();renderAll();applyRoute();
})();

