scripts/sourced-paths.mjs.beforeText:
// Pure, source-provenance-aware graph traversal. No runtime/UI modifications.
import fs from 'node:fs';
import vm from 'node:vm';
import {pathToFileURL} from 'node:url';

export function readGraph(directory='.') {
  const sandbox={window:{}};
  vm.createContext(sandbox);
  // Match the authoritative coverage pipeline's runtime source-registration order.
  for(const file of ['theories.js','developments.js','evidence.js','formulas.js',
                     'formula-audit.js','profiles.js','questions.js','problems.js','passports.js'])
    vm.runInContext(fs.readFileSync(directory+'/'+file,'utf8'),sandbox,{filename:file});
  return sandbox.window.QI_DATA;
}

const semantics='Shortest directed path through explicitly source-backed catalog edges only. Each edge remains a scoped claim, not a logical proof or causal implication between endpoints. Stored from/to direction is respected even for overlap links.';

export function shortestDocumentedPath(graph,fromId,toId,{maxHops=12}={}){
  if(!Number.isInteger(maxHops)||maxHops<0||maxHops>30)
    throw new RangeError('maxHops must be an integer between 0 and 30');
  const {theories,relations,sources}=graph;
  const byId=new Map(theories.map(t=>[t.id,t]));
  const bySource=new Map(sources.map(s=>[s.id,s]));
  const base={semantics,fromId,toId,maxHops};
  for(const id of [fromId,toId]){
    if(!byId.has(id))return {...base,found:false,reason:'unknown-theory-id',unknownId:id,nodes:[],edges:[]};
  }
  const node=id=>({id,name:byId.get(id).name,category:byId.get(id).category});
  if(fromId===toId)return {...base,found:true,hops:0,nodes:[node(fromId)],edges:[]};

  const adjacency=new Map();
  const accepted=new Set(['high','medium']);
  for(const rel of relations){
    if(!Array.isArray(rel.sourceIds)||rel.sourceIds.length===0||
       !accepted.has(rel.confidence)||rel.evidenceType==='editorial relation')continue;
    if(!byId.has(rel.from)||!byId.has(rel.to))throw new Error('Dangling documented relation');
    for(const id of rel.sourceIds)if(!bySource.has(id))throw new Error('Missing documented relation source: '+id);
    if(!adjacency.has(rel.from))adjacency.set(rel.from,[]);
    adjacency.get(rel.from).push(rel);
  }
  for(const list of adjacency.values())list.sort((a,b)=>
    (a.to+'|'+a.type+'|'+a.sourceIds.join(',')).localeCompare(b.to+'|'+b.type+'|'+b.sourceIds.join(',')));
  const queue=[fromId],visited=new Set(queue),depth=new Map([[fromId,0]]),parent=new Map();
  let reached=false;
  for(let i=0;i<queue.length&&!reached;i++){
    const here=queue[i],d=depth.get(here);
    if(d>=maxHops)continue;
    for(const edge of adjacency.get(here)||[]){
      if(visited.has(edge.to))continue;
      visited.add(edge.to);depth.set(edge.to,d+1);
      parent.set(edge.to,{from:here,edge});
      if(edge.to===toId){reached=true;break;}
      queue.push(edge.to);
    }
  }
  if(!reached)return {...base,found:false,reason:'no-directed-sourced-path-within-limit',nodes:[],edges:[]};
  const backward=[],ids=[toId];
  for(let id=toId;id!==fromId;){
    const step=parent.get(id);
    if(!step)throw new Error('Incomplete path reconstruction');
    const r=step.edge;
    backward.push({
      from:r.from,to:r.to,type:r.type,note:r.note||'',
      confidence:r.confidence,evidenceType:r.evidenceType,
      evidenceNote:r.evidenceNote||'',sourceLocator:r.sourceLocator||null,
      sourceIds:[...r.sourceIds],
      sources:r.sourceIds.map(id=>{
        const s=bySource.get(id);return {id,title:s.title,authors:s.authors,year:s.year,url:s.url};
      })
    });
    id=step.from;ids.push(id);
  }
  ids.reverse();backward.reverse();
  return {...base,found:true,hops:backward.length,nodes:ids.map(node),edges:backward};
}

if(process.argv[1]&&import.meta.url===pathToFileURL(process.argv[1]).href){
  const [from,to,max]=process.argv.slice(2);
  if(!from||!to){console.error('Usage: node scripts/sourced-paths.mjs <from-theory-id> <to-theory-id> [maxHops]');process.exitCode=2;}
  else {
    const limit=max===undefined?12:Number(max);
    try{
      const result=shortestDocumentedPath(readGraph(),from,to,{maxHops:limit});
      console.log(JSON.stringify(result,null,2));
      if(result.reason==='unknown-theory-id')process.exitCode=2;
    }catch(e){console.error(String(e));process.exitCode=2;}
  }
}

scripts/validate-data.mjs.beforeText:
import fs from "node:fs";
import vm from "node:vm";

const code = fs.readFileSync("theories.js","utf8");
const sandbox = { window: {} };
vm.createContext(sandbox);
vm.runInContext(code, sandbox);
const developmentCode = fs.readFileSync("developments.js","utf8");
vm.runInContext(developmentCode, sandbox);
const data = sandbox.window.QI_DATA;
const developmentData = sandbox.window.QI_DEVELOPMENTS;
// Evidence injects additional bibliography records used by the browser runtime.
vm.runInContext(fs.readFileSync("evidence.js","utf8"), sandbox);

const formulaCode = fs.readFileSync("formulas.js","utf8");
vm.runInContext(formulaCode, sandbox);
const formulaData = sandbox.window.QI_FORMULAS;
const formulaAuditCode = fs.readFileSync("formula-audit.js","utf8");
vm.runInContext(formulaAuditCode, sandbox);
const formulaAudit = sandbox.window.QI_FORMULA_AUDIT;

if (!data || !Array.isArray(data.theories) || !Array.isArray(data.relations) || !Array.isArray(data.trees) || !Array.isArray(data.sources)) {
  throw new Error("QI_DATA schema missing");
}
if (!developmentData || !Array.isArray(developmentData.events) || !Array.isArray(developmentData.eventTypes)) throw new Error("QI_DEVELOPMENTS schema missing");
if (!formulaData || !Array.isArray(formulaData.formulas)) throw new Error("QI_FORMULAS schema missing");
if (!formulaAudit || !Array.isArray(formulaAudit.entries)) throw new Error("QI_FORMULA_AUDIT schema missing");

const ids = data.theories.map(t=>t.id);
const unique = new Set(ids);
if (unique.size !== ids.length) throw new Error("Duplicate theory IDs");
if (data.theories.length < 464) throw new Error(`Expected exhaustive-breadth baseline >= 464 theories; found only ${data.theories.length}`);

if (new Set(data.theories.map(t=>t.category)).size < 14) throw new Error("Expected at least 14 top-level categories");

const sourceIds = data.sources.map(s=>s.id);
const uniqueSources = new Set(sourceIds);
if (uniqueSources.size !== sourceIds.length) throw new Error("Duplicate source IDs");
if (data.sources.length < 450) throw new Error(`Expected breadth-baseline bibliography >= 450 sources; found only ${data.sources.length}`);

for (const s of data.sources) {
  for (const key of ["id","title","authors","year","type","url"]) {
    if (s[key] === undefined || s[key] === null || s[key] === "") throw new Error(`Source ${s.id || "?"} missing ${key}`);
  }
  if (!String(s.url).startsWith("https://")) throw new Error(`Source ${s.id} is not HTTPS`);
}

for (const t of data.theories) {
  for (const key of ["id","name","year","era","category","status","kind","summary","core","provenance"]) {
    if (t[key] === undefined || t[key] === null || t[key] === "") throw new Error(`Theory ${t.id || "?"} missing ${key}`);
  }
  if (!Array.isArray(t.sources)) throw new Error(`Theory ${t.id} sources is not an array`);
  for (const sourceId of t.sources) {
    if (!uniqueSources.has(sourceId)) throw new Error(`Theory ${t.id} references missing source ${sourceId}`);
  }
  if (t.provenance !== "catalogued" && t.sources.length === 0) {
    throw new Error(`Theory ${t.id} claims provenance without a source`);
  }
}

const allowedRelationConfidence = new Set(["high","medium","editorial"]);
const allowedEvidenceTypes = new Set(["documented historical influence","formal mathematical relation","editorial relation"]);
for (const r of data.relations) {
  if (!unique.has(r.from) || !unique.has(r.to)) throw new Error(`Dangling relation ${r.from} -> ${r.to}`);
  if (!Array.isArray(r.sourceIds)) throw new Error(`Relation ${r.from}->${r.to} sourceIds must be an array`);
  if (!allowedEvidenceTypes.has(r.evidenceType)) throw new Error(`Relation ${r.from}->${r.to} has invalid evidenceType ${r.evidenceType}`);
  if (!allowedRelationConfidence.has(r.confidence)) throw new Error(`Relation ${r.from}->${r.to} has invalid confidence ${r.confidence}`);
  for (const sourceId of r.sourceIds) if (!uniqueSources.has(sourceId)) throw new Error(`Relation ${r.from}->${r.to} references missing source ${sourceId}`);
  if (r.confidence !== "editorial" && r.sourceIds.length === 0) throw new Error(`Non-editorial relation ${r.from}->${r.to} lacks evidence sources`);
}
const sourcedRelations = data.relations.filter(r=>r.sourceIds.length);
if (sourcedRelations.length < 57) throw new Error(`Expected at least 57 source-backed relations; found ${sourcedRelations.length}`);
for (const tree of data.trees) {
  for (const id of tree.nodes) if (!unique.has(id)) throw new Error(`Tree ${tree.name} references missing ${id}`);
  const nodeSet = new Set(tree.nodes);
  const connected = new Set();
  for (const r of data.relations) {
    if (nodeSet.has(r.from) && nodeSet.has(r.to)) {
      connected.add(r.from);
      connected.add(r.to);
    }
  }
  const isolated = tree.nodes.filter(id => !connected.has(id));
  if (isolated.length) throw new Error(`Tree ${tree.name} has isolated nodes: ${isolated.join(", ")}`);
}

const formulaIds = formulaData.formulas.map(f=>f.id);
const uniqueFormulaIds = new Set(formulaIds);
if (uniqueFormulaIds.size !== formulaIds.length) throw new Error("Duplicate formula IDs");
if (formulaData.formulas.length < 345) throw new Error(`Expected formula atlas >= 345 entries; found ${formulaData.formulas.length}`);

const allowedFormulaTypes = new Set(["exact","defining","canonical","schematic","approximation","limit","derived identity"]);
for (const f of formulaData.formulas) {
  for (const key of ["id","name","category","latex","plain","description","formulaType","regime","units","theoryRelationship","metadataReview"]) {
    if (f[key] === undefined || f[key] === null || f[key] === "") throw new Error(`Formula ${f.id || "?"} missing ${key}`);
  }
  if (!allowedFormulaTypes.has(f.formulaType)) throw new Error(`Formula ${f.id} has invalid formulaType ${f.formulaType}`);
  if (!Array.isArray(f.assumptions)) throw new Error(`Formula ${f.id} assumptions must be an array`);
  if (!Array.isArray(f.variables)) throw new Error(`Formula ${f.id} variables must be an array`);
  if (!Array.isArray(f.theoryIds) || !f.theoryIds.length) throw new Error(`Formula ${f.id} has no linked theory`);
  if (!Array.isArray(f.sourceIds) || !f.sourceIds.length) throw new Error(`Formula ${f.id} has no source`);
  for (const id of f.theoryIds) if (!unique.has(id)) throw new Error(`Formula ${f.id} references missing theory ${id}`);
  for (const id of f.sourceIds) if (!uniqueSources.has(id)) throw new Error(`Formula ${f.id} references missing source ${id}`);
  if (f.sourceLocations !== undefined) {
    if (!Array.isArray(f.sourceLocations)) throw new Error(`Formula ${f.id} sourceLocations must be an array`);
    for (const location of f.sourceLocations) {
      if (!f.sourceIds.includes(location.sourceId) || !location.locator?.trim() || !/^https:\/\//.test(location.url || "")) {
        throw new Error(`Formula ${f.id} has an invalid equation-level source location`);
      }
    }
  }
}

const auditTheoryIds = formulaAudit.entries.map(e=>e.theoryId);
if (new Set(auditTheoryIds).size !== auditTheoryIds.length) throw new Error("Duplicate theory IDs in formula audit");
if (auditTheoryIds.length !== ids.length) throw new Error(`Formula audit count ${auditTheoryIds.length} does not match theory count ${ids.length}`);
const allowedAuditClasses = new Set(["formula-bearing","formula-bearing-gap","primarily conceptual","theorem","interpretation","thought experiment"]);
for (const e of formulaAudit.entries) {
  if (!unique.has(e.theoryId)) throw new Error(`Formula audit references missing theory ${e.theoryId}`);
  if (!allowedAuditClasses.has(e.classification)) throw new Error(`Formula audit ${e.theoryId} has invalid classification ${e.classification}`);
  if (!Array.isArray(e.formulaIds)) throw new Error(`Formula audit ${e.theoryId} formulaIds must be an array`);
  for (const id of e.formulaIds) if (!uniqueFormulaIds.has(id)) throw new Error(`Formula audit ${e.theoryId} references missing formula ${id}`);
  if (e.classification === "formula-bearing" && !e.formulaIds.length) throw new Error(`Formula-bearing theory ${e.theoryId} has no formula`);
  if (e.classification === "formula-bearing-gap" && !e.gapReason) throw new Error(`Formula gap ${e.theoryId} lacks a documented reason`);
}



const developmentIds = developmentData.events.map(e=>e.id);
if (new Set(developmentIds).size !== developmentIds.length) throw new Error("Duplicate DevelopmentEvent IDs");
const allowedDevelopmentTypes = new Set(developmentData.eventTypes);
for (const event of developmentData.events) {
  for (const key of ["id","title","date","year","eventType","summary","significance","evidenceStatus","reviewedAt"]) {
    if (event[key] === undefined || event[key] === null || event[key] === "") throw new Error(`DevelopmentEvent ${event.id || "?"} missing ${key}`);
  }
  if (!/^\d{4}-\d{2}-\d{2}$/.test(event.date) || Number(event.date.slice(0,4)) !== event.year) throw new Error(`DevelopmentEvent ${event.id} has invalid date/year`);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(event.reviewedAt)) throw new Error(`DevelopmentEvent ${event.id} missing review date`);
  if (!allowedDevelopmentTypes.has(event.eventType)) throw new Error(`DevelopmentEvent ${event.id} has invalid eventType ${event.eventType}`);
  for (const key of ["relatedTheoryIds","relatedProblemIds","relatedFormulaIds","relatedEvidenceIds","sourceIds","sourceLocations"]) {
    if (!Array.isArray(event[key])) throw new Error(`DevelopmentEvent ${event.id} ${key} must be an array`);
  }
  if (!event.relatedTheoryIds.length) throw new Error(`DevelopmentEvent ${event.id} has no related theory`);
  if (!event.sourceIds.length || !event.sourceLocations.length) throw new Error(`DevelopmentEvent ${event.id} lacks source evidence`);
  for (const id of event.relatedTheoryIds) if (!unique.has(id)) throw new Error(`DevelopmentEvent ${event.id} references missing theory ${id}`);
  for (const id of event.relatedFormulaIds) if (!uniqueFormulaIds.has(id)) throw new Error(`DevelopmentEvent ${event.id} references missing formula ${id}`);
  for (const id of event.sourceIds) if (!uniqueSources.has(id)) throw new Error(`DevelopmentEvent ${event.id} references missing source ${id}`);
  for (const location of event.sourceLocations) {
    if (!event.sourceIds.includes(location.sourceId) || !location.locator?.trim() || !/^https:\/\//.test(location.url || "")) {
      throw new Error(`DevelopmentEvent ${event.id} has invalid source location`);
    }
  }
}

const cataloguedOnly = data.theories.filter(t=>t.provenance === "catalogued");
if (cataloguedOnly.length) {
  throw new Error(`Shipped theory remains catalogued-only: ${cataloguedOnly.map(t=>t.id).join(", ")}`);
}

const sourceBacked = data.theories.filter(t=>t.provenance !== "catalogued").length;
console.log(JSON.stringify({
  theories:data.theories.length,
  relations:data.relations.length,
  sourcedRelations:data.relations.filter(r=>r.sourceIds.length).length,
  editorialRelations:data.relations.filter(r=>r.confidence==="editorial").length,
  trees:data.trees.length,
  categories:[...new Set(data.theories.map(t=>t.category))].length,
  kinds:[...new Set(data.theories.map(t=>t.kind))].length,
  sources:data.sources.length,
  sourceBacked,
  sourceCoveragePct:Number((sourceBacked / data.theories.length * 100).toFixed(1)),
  formulas:formulaData.formulas.length,
  formulaCategories:[...new Set(formulaData.formulas.map(f=>f.category))].length,
  formulaTypes:[...new Set(formulaData.formulas.map(f=>f.formulaType))].length,
  formulaAuditCovered:formulaAudit.entries.filter(e=>e.classification==="formula-bearing").length,
  formulaAuditGaps:formulaAudit.entries.filter(e=>e.classification==="formula-bearing-gap").length,
  developmentEvents:developmentData.events.length,
  newestDevelopmentYear:Math.max(...developmentData.events.map(e=>e.year))
},null,2));

vm.runInContext(fs.readFileSync('profiles.js','utf8'), sandbox);
const research = sandbox.window.QI_PROFILES;
if (!research || Object.keys(research.profiles).length !== 59) throw new Error('Expected 59 curated research profiles');
for (const [id, profile] of Object.entries(research.profiles)) {
  if (!unique.has(id)) throw new Error(`Unknown profile entry: ${id}`);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(profile.reviewedAt)) throw new Error(`Missing review date: ${id}`);
  for (const key of ['problem','scope','assumptions','predictions','evidence','limitations','questions']) {
    const claim=profile[key];
    if (!claim?.text?.trim() || !claim.sourceIds?.length || claim.sourceIds.some(s=>!uniqueSources.has(s))) throw new Error(`Invalid cited profile field: ${id}/${key}`);
  }
  if (!Array.isArray(profile.prerequisites) || profile.prerequisites.some(p=>!unique.has(p)||p===id)) throw new Error(`Invalid prerequisite: ${id}`);
}
for (const preset of research.comparisons) {
  if (!preset.name || preset.theoryIds.length<2 || preset.theoryIds.length>4 || new Set(preset.theoryIds).size!==preset.theoryIds.length || preset.theoryIds.some(id=>!research.profiles[id])) throw new Error('Invalid comparison preset');
}
console.log('Validated 59 cited research profiles and comparison presets.');
for(const path of research.learningPaths){
  if(!path.id||!path.title||!path.goal||!path.prerequisites||path.steps.length<2)throw new Error('Invalid learning path');
  if(new Set(path.steps.map(s=>s.theoryId)).size!==path.steps.length)throw new Error('Duplicate path step');
  for(const step of path.steps)if(!unique.has(step.theoryId)||!research.profiles[step.theoryId]||!step.why)throw new Error('Invalid learning step');
  if(path.comparison.length<2||path.comparison.length>4||path.comparison.some(id=>!unique.has(id)))throw new Error('Invalid path comparison');
}
if(research.learningPaths.length!==5 || new Set(research.learningPaths.map(p=>p.id)).size!==5)throw new Error('Expected five distinct learning paths');

const primer=research.learningPaths.find(p=>p.id==='gravity-time').primer;
if(!primer?.equation || !primer.sourceLocator || primer.paragraphs.length!==3)throw new Error('Missing gravity and time primer');
for(const claim of primer.paragraphs)if(!claim.text || !claim.sourceIds.length || claim.sourceIds.some(id=>!uniqueSources.has(id)))throw new Error('Invalid primer citation');

